import { Textarea } from '@/components/ui/Textarea';
import { Select } from '@/components/ui/Select';
import { Icon } from '@/components/ui/Icon';
'use client';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';

import { useState, useEffect } from 'react';

export default function AdminQuestionsPage() {
    const [activeTab, setActiveTab] = useState('reports'); // 'reports' | 'all'
    const [questions, setQuestions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [search, setSearch] = useState('');
    const [showAddModal, setShowAddModal] = useState(false);

    // New Question Form State
    const [newQ, setNewQ] = useState({
        text: '', option_a: '', option_b: '', option_c: '', option_d: '', correct_option: 'A',
        subject_id: 1, chapter_id: 1, topic_id: 1, difficulty: 'medium',
        is_pyq: false, exam_name: '', year_asked: ''
    });

    useEffect(() => {
        fetchQuestions();
    }, [activeTab, search]);

    const fetchQuestions = async () => {
        setLoading(true);
        try {
            const url = `/api/admin/questions?mode=${activeTab}&search=${search}`;
            const res = await fetch(url);
            const data = await res.json();
            if (res.ok) setQuestions(data.questions);
        } catch (error) {
            console.error('Failed to fetch', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id) => {
        if (!confirm('Are you sure you want to delete this question?')) return;
        try {
            await fetch(`/api/admin/questions?id=${id}`, { method: 'DELETE' });
            fetchQuestions(); // Refresh
        } catch (e) { alert('Failed to delete'); }
    };

    const handleAddSubmit = async () => {
        try {
            const res = await fetch('/api/admin/questions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newQ)
            });
            if (res.ok) {
                alert('Question Added!');
                setShowAddModal(false);
                if (activeTab === 'all') fetchQuestions();
            } else {
                const d = await res.json();
                alert(d.error);
            }
        } catch (e) { alert('Failed to add'); }
    };

    return (
        <div className="p-8">
            <header className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold mb-2 bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">Question Manager</h1>
                    <div className="flex gap-6 mt-4">
                        <Button className={`pb-2 text-sm font-medium transition-all duration-300 border-b-2 ${activeTab === 'reports' ? 'border-accent text-accent' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                            onClick={() => setActiveTab('reports')}>
                            Quality Control 🚩
                        </Button>
                        <Button className={`pb-2 text-sm font-medium transition-all duration-300 border-b-2 ${activeTab === 'all' ? 'border-accent text-accent' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                            onClick={() => setActiveTab('all')}>
                            Question Bank <Icon name="BookOpen" />
                        </Button>
                    </div>
                </div>
                <Button className="btn btn-primary shadow-[0_0_20px_rgba(59,130,246,0.5)] hover:shadow-[0_0_30px_rgba(59,130,246,0.6)] transition-shadow" onClick={() => setShowAddModal(true)}>
                    + Add Question
                </Button>
            </header>

            {/* Toolbar for 'All' tab */}
            {activeTab === 'all' && (
                <div className="mb-6 flex gap-3">
                    <div className="relative flex-1 max-w-md group">
                        <div className="absolute inset-0 bg-accent/20 blur-md rounded-lg opacity-0 group-focus-within:opacity-100 transition-opacity"></div>
                        <Input
                            type="text"
                            placeholder="Search questions..."
                            className="relative w-full bg-black/50 border border-white/10 rounded-lg px-4 py-3 focus:outline-none focus:border-accent/50 text-white placeholder-gray-600 transition-colors"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                    <Button className="btn btn-secondary" onClick={fetchQuestions}>Search</Button>
                </div>
            )}

            {loading ? (
                <div className="flex justify-center p-12">
                    <div className="w-8 h-8 border-2 border-accent border-t-transparent rounded-full animate-spin"></div>
                </div>
            ) : (
                <div className="space-y-3">
                    {questions.map(q => (
                        <div key={q.id} className="group flex items-center gap-4 p-4 rounded-xl bg-white/5 border border-white/5 hover:border-accent/30 hover:bg-white/10 transition-all duration-300 relative overflow-hidden">
                            {/* Hover Glow */}
                            <div className="absolute inset-0 bg-gradient-to-r from-accent/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                            {/* ID & Icon */}
                            <div className="relative z-10 flex flex-col items-center justify-center w-14 h-14 rounded-lg bg-black/40 border border-white/10 shrink-0">
                                <span className="text-[10px] text-gray-500 font-mono">#{q.id}</span>
                                <span className="text-xl">{q.is_pyq ? '🏛️' : '<Icon name="FileText" />'}</span>
                            </div>

                            {/* Content */}
                            <div className="relative z-10 flex-1 min-w-0">
                                <div className="flex flex-wrap items-center gap-2 mb-1.5">
                                    {q.is_pyq && (
                                        <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider bg-purple-500/10 text-purple-400 border border-purple-500/20 shadow-[0_0_10px_rgba(168,85,247,0.1)]">
                                            PYQ {q.year_asked}
                                        </span>
                                    )}
                                    <span className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider border ${q.difficulty === 'hard' ? 'bg-red-500/10 text-red-400 border-red-500/20' :
                                        q.difficulty === 'medium' ? 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20' :
                                            'bg-green-500/10 text-green-400 border-green-500/20'
                                        }`}>
                                        {q.difficulty || 'Medium'}
                                    </span>
                                    {q.is_ai_generated === 1 && (
                                        <>
                                            <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider bg-blue-500/10 text-blue-400 border border-blue-500/20 shadow-[0_0_10px_rgba(59,130,246,0.1)]">
                                                <Icon name="Zap" /> AI
                                            </span>
                                            {q.confidence_score > 0 && (
                                                <span className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider border ${q.confidence_score >= 85 ? 'bg-green-500/10 text-green-400 border-green-500/20' :
                                                        q.confidence_score >= 50 ? 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20' :
                                                            'bg-red-500/10 text-red-400 border-red-500/20'
                                                    }`}>
                                                    {q.confidence_score}% Trust
                                                </span>
                                            )}
                                        </>
                                    )}
                                </div>
                                <p className="text-gray-200 line-clamp-1 font-medium group-hover:text-white transition-colors">{q.text}</p>
                                <p className="text-xs text-gray-600 mt-1 flex gap-3">
                                    <span>Topic: <span className="text-gray-400">{q.topic_id}</span></span>
                                    <span>Correct: <span className="text-green-400 font-bold">{q.correct_option}</span></span>
                                </p>
                            </div>

                            {/* Reports Info */}
                            {activeTab === 'reports' && (
                                <div className="hidden md:block w-48 text-right relative z-10">
                                    <p className="text-xs text-red-300 font-medium bg-red-900/20 px-2 py-1 rounded border border-red-500/20 inline-block">
                                        {q.reasons ? q.reasons.split(',')[0] : 'Reported'}
                                    </p>
                                </div>
                            )}

                            {/* Actions */}
                            <div className="relative z-10 flex gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-4 group-hover:translate-x-0">
                                <Button className="p-2.5 rounded-lg bg-blue-500/10 text-blue-400 hover:bg-blue-500 hover:text-white transition-colors border border-blue-500/20" title="Edit">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                </Button>
                                <Button onClick={() => handleDelete(q.id)} className="p-2.5 rounded-lg bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white transition-colors border border-red-500/20" title="Delete">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                </Button>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Add Modal */}
            {showAddModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-[#0f0f1a] border border-white/10 rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl animate-scale-in">
                        <div className="p-6 border-b border-white/5 flex justify-between items-center">
                            <h2 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">Add New Question</h2>
                            <Button onClick={() => setShowAddModal(false)} className="text-gray-500 hover:text-white"><Icon name="Star" size={16} /></Button>
                        </div>

                        <div className="p-6 space-y-4">
                            <div className="grid grid-cols-3 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs text-gray-500 uppercase">Subject ID</label>
                                    <Input className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent" type="number"
                                        value={newQ.subject_id} onChange={e => setNewQ({ ...newQ, subject_id: e.target.value })} />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs text-gray-500 uppercase">Chapter ID</label>
                                    <Input className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent" type="number"
                                        value={newQ.chapter_id} onChange={e => setNewQ({ ...newQ, chapter_id: e.target.value })} />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs text-gray-500 uppercase">Topic ID</label>
                                    <Input className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent" type="number"
                                        value={newQ.topic_id} onChange={e => setNewQ({ ...newQ, topic_id: e.target.value })} />
                                </div>
                            </div>

                            <div className="space-y-1">
                                <label className="text-xs text-gray-500 uppercase">Difficulty</label>
                                <Select className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent"
                                    value={newQ.difficulty} onChange={e => setNewQ({ ...newQ, difficulty: e.target.value })}>
                                    <option value="easy">Easy</option>
                                    <option value="medium">Medium</option>
                                    <option value="hard">Hard</option>
                                </Select>
                            </div>

                            <div className="space-y-1">
                                <label className="text-xs text-gray-500 uppercase">Question Text</label>
                                <Textarea className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent min-h-[100px]"
                                    value={newQ.text} onChange={e => setNewQ({ ...newQ, text: e.target.value })}></Textarea>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                {['A', 'B', 'C', 'D'].map(opt => (
                                    <div key={opt} className="space-y-1">
                                        <label className="text-xs text-gray-500 uppercase">Option {opt}</label>
                                        <div className="relative">
                                            <span className="absolute left-3 top-2.5 text-gray-600 font-bold">{opt}</span>
                                            <Input className="w-full bg-black/50 border border-white/10 rounded-lg pl-8 pr-3 py-2 text-white focus:border-accent"
                                                value={newQ[`option_${opt.toLowerCase()}`]}
                                                onChange={e => setNewQ({ ...newQ, [`option_${opt.toLowerCase()}`]: e.target.value })} />
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="space-y-1">
                                <label className="text-xs text-gray-500 uppercase">Correct Option</label>
                                <Select className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent"
                                    value={newQ.correct_option} onChange={e => setNewQ({ ...newQ, correct_option: e.target.value })}>
                                    <option value="A">Option A</option>
                                    <option value="B">Option B</option>
                                    <option value="C">Option C</option>
                                    <option value="D">Option D</option>
                                </Select>
                            </div>

                            <div className="p-4 rounded-lg bg-white/5 border border-white/10">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <Input type="checkbox" className="w-5 h-5 rounded border-gray-600 text-accent focus:ring-accent bg-gray-700"
                                        checked={newQ.is_pyq} onChange={e => setNewQ({ ...newQ, is_pyq: e.target.checked })} />
                                    <span className="font-medium text-white">Is Previous Year Question (PYQ)?</span>
                                </label>
                                {newQ.is_pyq && (
                                    <div className="grid grid-cols-2 gap-4 mt-3 animate-fade-in-down">
                                        <Input className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent"
                                            placeholder="Exam Name (e.g. NEET)" value={newQ.exam_name} onChange={e => setNewQ({ ...newQ, exam_name: e.target.value })} />
                                        <Input className="w-full bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-accent"
                                            placeholder="Year (e.g. 2023)" value={newQ.year_asked} onChange={e => setNewQ({ ...newQ, year_asked: e.target.value })} />
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="p-6 border-t border-white/5 flex justify-end gap-3">
                            <Button className="btn btn-ghost hover:bg-white/5" onClick={() => setShowAddModal(false)}>Cancel</Button>
                            <Button className="btn btn-primary px-8" onClick={handleAddSubmit}>Save Question</Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import { Icon } from '@/components/ui/Icon';
'use client';
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import useSWR from 'swr';
import { fetcher } from '@/lib/swr';
import { ScoreTrendChart, SubjectRadarChart } from '@/components/Charts';
import { useAuth } from '@/context/AuthContext';
import { Card, Button } from '@/components/ui';
import { AnalyticsSkeleton } from '@/components/skeletons';
import { EmptyState } from '@/components/ui/EmptyState';
import { openWhatsAppShare } from '@/lib/utils/whatsapp';

export default function AnalyticsPage() {
    const router = useRouter();
    const { user, loading: authLoading } = useAuth();
    useEffect(() => {
        if (authLoading) return;
        if (!user) { window.location.href = '/login'; }
    }, [user, authLoading]);

    const { data, error, isLoading: isSwrLoading } = useSWR(
        !authLoading && user ? '/api/performance' : null,
        fetcher,
        { revalidateOnFocus: true }
    );

    useEffect(() => {
        if (error) {
            window.location.href = '/login';
        }
    }, [error]);

    const loading = authLoading || isSwrLoading || (!data && !error);

    if (loading) return (
        <div style={{ minHeight: '100vh' }}>
            <AnalyticsSkeleton />
        </div>
    );

    const { subjectPerformance, chapterStrength, weakAreas, strongAreas, testHistory, overallStats, rankPrediction } = data || {};

    return (
        <div>
            <div className="page">
                <div className="page-header">
                    <h1 className="page-title"><Icon name="TrendingUp" /> Performance Analytics</h1>
                    <p className="page-subtitle">Your complete NEET preparation insights</p>
                </div>

                {/* Empty State */}
                {(!testHistory || testHistory.length === 0) && (
                    <div style={{ marginTop: 32 }}>
                        <EmptyState
                            type="analytics"
                            onAction={() => router.push('/test/configure')}
                        />
                    </div>
                )}

                {/* Charts Section */}
                {testHistory && testHistory.length > 0 && (
                    <div className="grid grid-2" style={{ gap: 24, marginBottom: 24 }}>
                        <Card>
                            <ScoreTrendChart data={
                                [...testHistory].reverse().map(t => ({ date: t.completed_at, score: t.score }))
                            } />
                        </Card>
                        <Card>
                            <SubjectRadarChart data={
                                (subjectPerformance || []).reduce((acc, curr) => ({ ...acc, [curr.name]: curr.avg_accuracy }), {})
                            } />
                        </Card>
                    </div>
                )}

                {/* Overall Stats */}
                <div className="grid grid-4" style={{ marginBottom: 24 }}>
                    <Card className="analytics-stat-card">
                        <div className="analytics-stat-icon"><Icon name="FileText" /></div>
                        <div className="analytics-stat-value">{overallStats?.total_tests || 0}</div>
                        <div className="analytics-stat-label">Total Tests</div>
                    </Card>
                    <Card className="analytics-stat-card">
                        <div className="analytics-stat-icon"><Icon name="Target" /></div>
                        <div className="analytics-stat-value">{overallStats?.avg_accuracy || 0}%</div>
                        <div className="analytics-stat-label">Avg Accuracy</div>
                    </Card>
                    <Card className="analytics-stat-card">
                        <div className="analytics-stat-icon"><Icon name="Star" size={16} /></div>
                        <div className="analytics-stat-value">{Math.round(overallStats?.avg_score || 0)}</div>
                        <div className="analytics-stat-label">Avg Score / 720</div>
                    </Card>
                    <Card className="analytics-stat-card">
                        <div className="analytics-stat-icon"><Icon name="Trophy" /></div>
                        <div className="analytics-stat-value">{Math.round(overallStats?.best_score || 0)}</div>
                        <div className="analytics-stat-label">Best Score / 720</div>
                    </Card>
                </div>

                {/* Subject Performance */}
                <Card style={{ marginBottom: 24 }}>
                    <h2 className="analytics-section-title"><Icon name="BarChart2" /> Subject-wise Performance</h2>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                        {(subjectPerformance || []).map(s => (
                            <div key={s.id}>
                                <div className="analytics-subject-row">
                                    <div className="analytics-subject-row-left">
                                        <span>{s.icon}</span>
                                        <span className="analytics-subject-name">{s.name}</span>
                                    </div>
                                    <span style={{ fontWeight: 700, color: s.color }}>{Math.round(s.avg_accuracy)}%</span>
                                </div>
                                <div className="analytics-bar-track">
                                    <div
                                        className="analytics-bar-fill"
                                        style={{ width: `${Math.round(s.avg_accuracy)}%`, background: `linear-gradient(90deg, ${s.color}88, ${s.color})` }}
                                    />
                                </div>
                                <div className="analytics-bar-meta">{s.total_attempted} questions attempted • {s.total_correct} correct</div>
                            </div>
                        ))}
                    </div>
                </Card>

                {/* Weak & Strong Areas */}
                <div className="grid grid-2" style={{ gap: 24, marginBottom: 24 }}>
                    <Card >
                        <h3 className="analytics-section-title-sm"><Icon name="AlertCircle" /> Weak Areas</h3>
                        {weakAreas && weakAreas.length > 0 ? (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                                {weakAreas.map((w, i) => (
                                    <div key={i} className="analytics-area-item">
                                        <div className="analytics-area-header">
                                            <div className="analytics-area-name">{w.topic_name}</div>
                                            <span style={{ fontWeight: 700 }}>{Math.round(w.accuracy)}%</span>
                                        </div>
                                        <div className="analytics-area-meta">{w.chapter_name} • {w.subject_name}</div>
                                        <div className="analytics-mini-bar-track">
                                            <div className="analytics-mini-bar-fill" style={{ width: `${w.accuracy}%` }} />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div style={{ padding: 20, textAlign: 'center' }}>
                                <p className="analytics-area-meta">Take more tests to identify weak areas</p>
                            </div>
                        )}
                    </Card>

                    <Card >
                        <h3 className="analytics-section-title-sm"><Icon name="Star" size={16} /> Strong Areas</h3>
                        {strongAreas && strongAreas.length > 0 ? (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                                {strongAreas.map((s, i) => (
                                    <div key={i} className="analytics-area-item">
                                        <div className="analytics-area-header">
                                            <div className="analytics-area-name">{s.topic_name}</div>
                                            <span style={{ fontWeight: 700 }}>{Math.round(s.accuracy)}%</span>
                                        </div>
                                        <div className="analytics-area-meta">{s.chapter_name} • {s.subject_name}</div>
                                        <div className="analytics-mini-bar-track">
                                            <div className="analytics-mini-bar-fill" style={{ width: `${s.accuracy}%` }} />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div style={{ padding: 20, textAlign: 'center' }}>
                                <p className="analytics-area-meta">Keep practicing to build strong areas</p>
                            </div>
                        )}
                    </Card>
                </div>

                {/* Rank Prediction */}
                <Card style={{ position: 'relative', overflow: 'hidden', marginBottom: 24 }}>
                    <h2 className="analytics-section-title"><Icon name="Trophy" /> Rank Prediction</h2>

                    {(user?.referrals_count || 0) < 1 && (
                        <div className="analytics-lock-overlay">
                            <div className="analytics-lock-icon"><Icon name="Lock" /></div>
                            <h3 className="analytics-lock-title">Premium Analytics Locked</h3>
                            <p className="analytics-lock-body">Refer 1 friend to unlock your AIR prediction</p>
                            <Button
                                variant="primary"
                                onClick={() => {
                                    const text = `Prepare for NEET 2026 with AI! <Icon name="Brain" />\n\nJoin me: https://aineetcoach.com/register?ref=${user?.referral_code || ''}`;
                                    openWhatsAppShare(text);
                                }}
                            >
                                📱 Share &amp; Unlock
                            </Button>
                        </div>
                    )}

                    <div className="analytics-rank-grid">
                        <div className="analytics-rank-item">
                            <div className="analytics-rank-value" >{rankPrediction?.predictedScore || 0}</div>
                            <div className="analytics-rank-label">Predicted Score</div>
                        </div>
                        <div className="analytics-rank-item">
                            <div className="analytics-rank-value" >#{(rankPrediction?.predictedRank || 0).toLocaleString()}</div>
                            <div className="analytics-rank-label">Predicted Rank</div>
                        </div>
                        <div className="analytics-rank-item">
                            <div className="analytics-rank-value" >{rankPrediction?.percentile || 0}%</div>
                            <div className="analytics-rank-label">Percentile</div>
                        </div>
                        <div className="analytics-rank-item">
                            <div className="analytics-rank-value" >{rankPrediction?.improvementProbability || 0}%</div>
                            <div className="analytics-rank-label">Improvement Prob.</div>
                        </div>
                    </div>
                    <p className="analytics-rank-footer">{rankPrediction?.collegePossibility}</p>
                </Card>

                {/* Chapter Strength */}
                {chapterStrength && chapterStrength.length > 0 && (
                    <Card style={{ marginBottom: 24 }}>
                        <h2 className="analytics-section-title"><Icon name="Star" size={16} /> Chapter Strength</h2>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                            {chapterStrength.map((c, i) => (
                                <div key={i} className="analytics-chapter-row">
                                    <span className="analytics-chapter-name">{c.name}</span>
                                    <div className="analytics-bar-track" style={{ flex: 1 }}>
                                        <div style={{
                                            background: c.accuracy >= 70 ? 'var(--success)' : c.accuracy >= 40 ? 'var(--warning)' : 'var(--danger)',
                                            width: `${c.accuracy}%`,
                                            height: '100%',
                                            }} />
                                    </div>
                                    <span className="analytics-chapter-pct">{Math.round(c.accuracy)}%</span>
                                </div>
                            ))}
                        </div>
                    </Card>
                )}

                {/* Test History */}
                {testHistory && testHistory.length > 0 && (
                    <Card>
                        <h2 className="analytics-section-title"><Icon name="FileText" /> Test History</h2>
                        <div className="analytics-table-wrapper">
                            <table className="analytics-table">
                                <thead>
                                    <tr>
                                        <th>Type</th>
                                        <th className="center">Score</th>
                                        <th className="center">Correct</th>
                                        <th className="center">Accuracy</th>
                                        <th className="right">Date</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {testHistory.map((t, i) => (
                                        <tr key={i}>
                                            <td>{t.type.charAt(0).toUpperCase() + t.type.slice(1)}</td>
                                            <td className="score">{Math.round(t.score)}/720</td>
                                            <td className="center">{t.correct_count}/{t.total_questions}</td>
                                            <td className="center">{t.total_questions > 0 ? Math.round(t.correct_count / t.total_questions * 100) : 0}%</td>
                                            <td className="right">{new Date(t.completed_at).toLocaleDateString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </Card>
                )}
            </div>
        </div>
    );
}

import { Icon } from '@/components/ui/Icon';
'use client';
import { Button } from '@/components/ui/Button';
import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';

export default function BattlePage() {
    const { user } = useAuth();
    const router = useRouter();
    const [gameState, setGameState] = useState('lobby'); // lobby | matching | playing | calculating | result
    const [opponent, setOpponent] = useState(null);
    const [questions, setQuestions] = useState([]);
    const [currentQ, setCurrentQ] = useState(0);
    const [userScore, setUserScore] = useState(0);
    const [oppScore, setOppScore] = useState(0);
    const [timeLeft, setTimeLeft] = useState(15);
    const [userAnswered, setUserAnswered] = useState(false);
    const [oppAnswered, setOppAnswered] = useState(false);
    const [logs, setLogs] = useState([]);
    const [resultData, setResultData] = useState(null);
    const [selectedOption, setSelectedOption] = useState(null);

    const aiTimerRef = useRef(null);
    const countdownRef = useRef(null);

    const startBattle = async () => {
        // Guard: redirect unauthenticated users to login
        if (!user) {
            window.location.href = '/login?redirect=/battle';
            return;
        }
        setGameState('matching');
        setUserScore(0);
        setOppScore(0);
        setCurrentQ(0);
        setLogs([]);
        setSelectedOption(null);

        try {
            const res = await fetch('/api/battle/create', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({})
            });
            const data = await res.json();
            if (res.ok) {
                setOpponent(data.opponent);
                setQuestions(data.questions);
                setTimeout(() => setGameState('playing'), 2000);
            } else {
                alert(data.error || 'Could not start battle. Please try again.');
                setGameState('lobby');
            }
        } catch (e) {
            console.error('Battle start error:', e);
            alert('Connection error. Please check your network and try again.');
            setGameState('lobby');
        }
    };

    // Game loop — runs per question
    useEffect(() => {
        if (gameState !== 'playing' || !questions.length) return;

        setTimeLeft(15);
        setUserAnswered(false);
        setOppAnswered(false);
        setSelectedOption(null);

        // AI opponent simulation  
        const aiTime = Math.random() * (opponent.maxTime - opponent.minTime) + opponent.minTime;
        const aiWillBeCorrect = Math.random() < opponent.accuracy;

        aiTimerRef.current = setTimeout(() => {
            setOppAnswered(true);
            if (aiWillBeCorrect) {
                setOppScore(prev => prev + 100);
                addLog(`${opponent.name} answered correctly! <Icon name="Target" />`);
            } else {
                addLog(`${opponent.name} got it wrong! <Icon name="XCircle" />`);
            }
        }, aiTime * 1000);

        // Countdown timer
        countdownRef.current = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    nextQuestion();
                    return 15;
                }
                return prev - 1;
            });
        }, 1000);

        return () => {
            clearInterval(countdownRef.current);
            clearTimeout(aiTimerRef.current);
        };
    }, [currentQ, gameState]);

    const handleUserAnswer = (option) => {
        if (userAnswered) return;
        setUserAnswered(true);
        setSelectedOption(option);

        const q = questions[currentQ];
        if (option === q.correct_option) {
            const points = 100 + (timeLeft * 2);
            setUserScore(prev => prev + points);
            addLog(`You answered correctly! <Icon name="CheckCircle" /> (+${points})`);
        } else {
            addLog(`Wrong answer! The correct one was ${q.correct_option} 😬`);
        }
    };

    const nextQuestion = () => {
        if (currentQ < questions.length - 1) {
            setCurrentQ(prev => prev + 1);
        } else {
            endBattle();
        }
    };

    const endBattle = async () => {
        setGameState('calculating');
        clearInterval(countdownRef.current);
        clearTimeout(aiTimerRef.current);

        const outcome = userScore > oppScore ? 'win' : (userScore < oppScore ? 'loss' : 'draw');

        try {
            const res = await fetch('/api/battle/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    battleId: `battle-${Date.now()}`,
                    opponentId: opponent.id,
                    userScore,
                    opponentScore: oppScore,
                    outcome
                })
            });
            const data = await res.json();
            setResultData({ ...data, outcome });
            setGameState('result');
        } catch (e) {
            console.error(e);
            setGameState('lobby');
        }
    };

    const addLog = (msg) => {
        setLogs(prev => [msg, ...prev].slice(0, 4));
    };

    // ===== LOBBY =====
    if (gameState === 'lobby') return (
        <div>

            <div className="page" style={{ maxWidth: 700, textAlign: 'center' }}>
                <div className="page-header">
                    <h1 className="page-title"><Icon name="Star" size={16} />️ 1v1 AI Battle Arena</h1>
                    <p className="page-subtitle">Challenge AI opponents in a rapid-fire 5-question duel. Gain ELO to climb the ranks!</p>
                </div>

                <div className="card" style={{ padding: '48px 32px' }}>
                    <div style={{ marginBottom: 24 }}><Icon name="Cpu" /></div>
                    <h2 style={{ fontWeight: 800, marginBottom: 12 }}>Ready for Battle?</h2>
                    <p className="text-muted" style={{ marginBottom: 32, maxWidth: 400, margin: '0 auto 32px' }}>
                        You'll face an AI opponent matched to your skill level. 5 questions, 15 seconds each. Fastest and most accurate wins!
                    </p>
                    <Button className="btn btn-primary btn-lg" onClick={startBattle} style={{ padding: '18px 48px' }}>
                        🎮 Find Opponent
                    </Button>
                </div>

                <div className="card" style={{ marginTop: 24, textAlign: 'left' }}>
                    <h3 className="mb-3"><Icon name="BarChart2" /> How ELO Works</h3>
                    <div className="text-sm text-muted" style={{ lineHeight: 1.8 }}>
                        <div><Icon name="Star" size={16} /> <strong>Win against stronger opponent</strong> → Big ELO gain</div>
                        <div><Icon name="Star" size={16} /> <strong>Win against weaker opponent</strong> → Small ELO gain</div>
                        <div><Icon name="Star" size={16} /> <strong>Lose against weaker opponent</strong> → Big ELO drop</div>
                        <div style={{ marginTop: 12, opacity: 0.7 }}>Starting ELO: 1000 • K-factor: 32</div>
                    </div>
                </div>
            </div>
        </div>
    );

    // ===== MATCHMAKING =====
    if (gameState === 'matching') return (
        <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', textAlign: 'center' }}>
            <div>
                <div className="spinner" style={{ width: 60, height: 60, margin: '0 auto 24px' }}></div>
                <h1 style={{ fontWeight: 900, marginBottom: 12 }}>SEARCHING FOR OPPONENT...</h1>
                <p className="text-muted">Matching skill levels based on your ELO rating...</p>
            </div>
        </div>
    );

    // ===== PLAYING =====
    if (gameState === 'playing' && questions.length > 0) {
        const q = questions[currentQ];
        const timerColor = timeLeft <= 5 ? '#ef4444' : timeLeft <= 10 ? '#f59e0b' : '#10b981';

        return (
            <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
                {/* HUD */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 24px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
                    <div style={{ textAlign: 'center' }}>
                        <div style={{ textTransform: 'uppercase', letterSpacing: 1 }}>You</div>
                        <div style={{ fontWeight: 900, }}>{userScore}</div>
                    </div>
                    <div style={{ textAlign: 'center' }}>
                        <div style={{ fontWeight: 900, color: timerColor, fontFamily: 'monospace' }}>{timeLeft}</div>
                        <div >Q{currentQ + 1}/5</div>
                    </div>
                    <div style={{ textAlign: 'center' }}>
                        <div style={{ textTransform: 'uppercase', letterSpacing: 1 }}>{opponent?.name}</div>
                        <div style={{ fontWeight: 900, }}>{oppScore}</div>
                        {oppAnswered && <div ><Icon name="Star" size={16} /> Answered</div>}
                    </div>
                </div>

                {/* Question */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 24, maxWidth: 700, margin: '0 auto', width: '100%' }}>
                    <div style={{ width: '100%', marginBottom: 32 }}>
                        <div style={{ textAlign: 'center', marginBottom: 20 }}>
                            <span style={{ padding: '6px 16px', }}>
                                Question {currentQ + 1} of {questions.length}
                            </span>
                        </div>
                        <h2 style={{ lineHeight: 1.6, textAlign: 'center', fontWeight: 600 }}>{q.text}</h2>
                    </div>

                    {/* Options */}
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, width: '100%' }}>
                        {['A', 'B', 'C', 'D'].map(opt => {
                            const isSelected = selectedOption === opt;
                            const isCorrect = q.correct_option === opt;
                            const showResult = userAnswered;

                            let borderColor = 'rgba(255,255,255,0.1)';
                            let bg = 'rgba(255,255,255,0.03)';
                            if (showResult && isCorrect) { borderColor = '#10b981'; bg = 'rgba(16,185,129,0.1)'; }
                            else if (showResult && isSelected && !isCorrect) { borderColor = '#ef4444'; bg = 'rgba(239,68,68,0.1)'; }
                            else if (!showResult) { borderColor = 'rgba(255,255,255,0.15)'; }

                            return (
                                <Button
                                    key={opt}
                                    disabled={userAnswered}
                                    onClick={() => handleUserAnswer(opt)}
                                    style={{
                                        padding: '20px 16px', border: `2px solid ${borderColor}`,
                                        background: bg, cursor: userAnswered ? 'default' : 'pointer',
                                        transition: 'all 0.2s', textAlign: 'left',
                                        transform: !userAnswered ? undefined : undefined,
                                    }}
                                    onMouseOver={(e) => { if (!userAnswered) e.target.style.transform = 'scale(1.03)'; }}
                                    onMouseOut={(e) => { e.target.style.transform = 'scale(1)'; }}
                                >
                                    <span style={{ fontWeight: 700, marginRight: 10, opacity: 0.5 }}>{opt}.</span>
                                    {q[`option_${opt.toLowerCase()}`]}
                                </Button>
                            );
                        })}
                    </div>

                    {/* Next button */}
                    {userAnswered && (
                        <Button onClick={nextQuestion} className="btn btn-primary" style={{ marginTop: 24, padding: '14px 48px', }}>
                            {currentQ < questions.length - 1 ? 'Next Question →' : '🏁 Finish Battle'}
                        </Button>
                    )}

                    {/* Battle Log */}
                    <div style={{ marginTop: 24, minHeight: 80, textAlign: 'center' }}>
                        {logs.map((l, i) => (
                            <div key={i} style={{ opacity: 1 - (i * 0.25), padding: '4px 0' }}>{l}</div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    // ===== CALCULATING =====
    if (gameState === 'calculating') return (
        <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', }}>
            <div style={{ textAlign: 'center' }}>
                <div className="spinner" style={{ width: 50, height: 50, margin: '0 auto 24px' }}></div>
                <h2 style={{ fontWeight: 800 }}>Calculating ELO...</h2>
            </div>
        </div>
    );

    // ===== RESULT =====
    if (gameState === 'result' && resultData) {
        const isWin = resultData.outcome === 'win';
        const isDraw = resultData.outcome === 'draw';

        return (
            <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', }}>
                <div className="card" style={{ maxWidth: 500, width: '100%', textAlign: 'center', padding: '48px 32px', border: `2px solid ${isWin ? 'var(--text-primary)' : isDraw ? 'var(--text-primary)' : 'var(--text-primary)'}30` }}>
                    <div style={{ marginBottom: 16 }}>
                        {isWin ? '<Icon name="Trophy" />' : isDraw ? '🤝' : '💀'}
                    </div>
                    <h1 style={{ fontWeight: 900, marginBottom: 8, color: isWin ? 'var(--text-primary)' : isDraw ? 'var(--text-primary)' : 'var(--text-primary)' }}>
                        {isWin ? 'VICTORY!' : isDraw ? 'DRAW!' : 'DEFEAT'}
                    </h1>

                    <div style={{ display: 'flex', justifyContent: 'center', gap: 48, margin: '32px 0', }}>
                        <div>
                            <div className="text-muted text-sm">You</div>
                            <div style={{ fontWeight: 900, }}>{userScore}</div>
                        </div>
                        <div style={{ opacity: 0.3 }}>vs</div>
                        <div>
                            <div className="text-muted text-sm">{opponent?.name}</div>
                            <div style={{ fontWeight: 900, }}>{oppScore}</div>
                        </div>
                    </div>

                    <div className="card" style={{ marginBottom: 32 }}>
                        <div className="text-muted text-sm" style={{ marginBottom: 8 }}>New ELO Rating</div>
                        <div style={{ fontWeight: 900, }}>{resultData.newElo}</div>
                        <div style={{ fontWeight: 700, color: resultData.eloChange >= 0 ? 'var(--text-primary)' : 'var(--text-primary)' }}>
                            {resultData.eloChange >= 0 ? '+' : ''}{resultData.eloChange} ELO
                        </div>
                    </div>

                    <div style={{ display: 'flex', gap: 12, justifyContent: 'center' }}>
                        <Button onClick={startBattle} className="btn btn-primary" style={{ padding: '14px 32px' }}>
                            ⚔️ Battle Again
                        </Button>
                        <a href="/dashboard" className="btn btn-secondary" style={{ padding: '14px 32px' }}>
                            🏠 Dashboard
                        </a>
                    </div>
                </div>
            </div>
        );
    }

    // Fallback
    return (
        <div className="loading-overlay" style={{ minHeight: '100vh' }}>
            <div className="spinner" style={{ width: 40, height: 40 }}></div>
        </div>
    );
}

