export default function RevisionPage() {
    const [reviews, setReviews] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [showAnswer, setShowAnswer] = useState(false);
    const [loading, setLoading] = useState(true);
    const router = useRouter();

    useEffect(() => {
        fetch('/api/revision/due')
            .then(res => res.json())
            .then(data => {
                setReviews(data.reviews || []);
                setLoading(false);
            })
            .catch(err => {
                console.error(err);
                setLoading(false);
            });
    }, []);

    const handleRate = async (quality) => {
        const currentCard = reviews[currentIndex];
        if (!currentCard) return;

        try {
            await fetch('/api/revision/log', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ questionId: currentCard.question_id, quality })
            });

            // Move to next card
            setShowAnswer(false);
            if (currentIndex < reviews.length - 1) {
                setCurrentIndex(prev => prev + 1);
            } else {
                // Done
                alert('Session Complete! Great job.');
                window.location.href = '/';
            }
        } catch (err) {
            console.error('Failed to log review', err);
        }
    };

    if (loading) return <div style={{ padding: 32, textAlign: 'center', }}>Loading your mission...</div>;

    if (reviews.length === 0) {
        return (
            <div className="page" style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
                    <Card style={{ textAlign: 'center', padding: 32, maxWidth: 450, width: '100%' }}>
                        <div style={{ marginBottom: 16 }}><Icon name="Star" size={16} /></div>
                        <h2 style={{ fontWeight: 800, marginBottom: 8, }}>All caught up!</h2>
                        <p style={{ marginBottom: 0, }}>You have no pending revisions for today.</p>
                        <Button variant="primary" onClick={() => window.location.href = '/'} style={{ width: '100%' }}>
                            Back to Dashboard
                        </Button>
                    </Card>
                </div>
            </div>
        );
    }

    const currentCard = reviews[currentIndex];

    return (
        <div className="page" style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', }}>

            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
                <div style={{ width: '100%', maxWidth: 650 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 0, }}>
                        <span style={{ fontWeight: 600 }}>Card {currentIndex + 1} / {reviews.length}</span>
                        <Badge variant="primary">{currentCard.subject_name}</Badge>
                    </div>

                    <Card style={{ padding: 32, minHeight: 300, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center', boxShadow: 'var(--shadow-lg)' }}>
                        <h3 style={{ fontWeight: 500, marginBottom: 0, lineHeight: 1.6 }}>{currentCard.text}</h3>

                        {!showAnswer && (
                            <Button
                                variant="primary"
                                size="lg"
                                onClick={() => setShowAnswer(true)}
                                style={{ marginTop: 0, }}
                            >
                                Show Answer
                            </Button>
                        )}

                        {showAnswer && (
                            <div className="animate-fade-in" style={{ width: '100%' }}>
                                <div style={{ padding: 16, border: '1px solid var(--success)', marginBottom: 32, textAlign: 'left', width: '100%' }}>
                                    <p style={{ fontWeight: 700, marginBottom: 8 }}>Correct Answer:</p>
                                    <p style={{ marginBottom: currentCard.explanation ? '8px' : 0 }}>Option {currentCard.correct_option}</p>
                                    {currentCard.explanation && (
                                        <p style={{ marginTop: 0, borderTop: 0, solid var(--border)', paddingTop: 0, }}>{currentCard.explanation}</p>
                                    )}
                                </div>

                                <div className="grid grid-3" style={{ gap: 16, width: '100%' }}>
                                    <Button
                                        variant="danger"
                                        onClick={() => handleRate(1)}
                                        style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: 12, height: 'auto' }}
                                    >
                                        <span style={{ fontWeight: 700 }}>Hard (1)</span>
                                        <span style={{ display: 'block', opacity: 0.8, marginTop: 0, }}>Review Tomorrow</span>
                                    </Button>
                                    <Button
                                        variant="secondary"
                                        onClick={() => handleRate(3)}
                                        style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: 12, height: 'auto' }}
                                    >
                                        <span style={{ fontWeight: 700 }}>Good (3)</span>
                                        <span style={{ display: 'block', opacity: 0.8, marginTop: 0, }}>Review in 3d</span>
                                    </Button>
                                    <Button
                                        variant="success"
                                        onClick={() => handleRate(5)}
                                        style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: 12, height: 'auto' }}
                                    >
                                        <span style={{ fontWeight: 700 }}>Easy (5)</span>
                                        <span style={{ display: 'block', opacity: 0.8, marginTop: 0, }}>Review in 7d</span>
                                    </Button>
                                </div>
                            </div>
                        )}
                    </Card>
                </div>
            </div>
        </div>
    );
}

import { Icon } from '@/components/ui/Icon';
'use client';
import { useState, useEffect, useCallback, useRef, use } from 'react';
import { useRouter } from 'next/navigation';
import MathRenderer from '@/components/MathRenderer';
import { OfflineStorage, TestSessionStore } from '@/lib/idb';
import { STORAGE_KEYS } from '@/lib/storage-resilient';
import { useMutation } from '@tanstack/react-query';
import { Card, Button, Badge, Select, Textarea } from '@/components/ui';
import { AutosaveIndicator, TrustBadge } from '@/components/trust/TrustBadge';
import { RecoveryBanner } from '@/components/trust/RecoveryBanner';

/**
 * P0-1 Trust Hardening: Test Page with Durable State Persistence
 * 
 * Architecture:
 *   IndexedDB = canonical source of truth (full test session)
 *   localStorage = fast recovery signal only (activeTestId flag)
 *   sessionStorage = initial test data handoff from configure page
 *   Server = timer truth (started_at timestamp)
 * 
 * Persistence triggers:
 *   - Every answer change
 *   - Every navigation
 *   - Every mark toggle
 *   - Every 10 seconds (heartbeat)
 *   - On visibilitychange (tab switch/minimize)
 *   - On beforeunload (tab close/refresh)
 * 
 * Recovery flow:
 *   On mount → check IDB for session → show Resume/Discard prompt → restore
 */

export default function TestPage({ params }) {
    const { id: testId } = use(params);
    const router = useRouter();

    // ─── Core State ───
    const [testData, setTestData] = useState(null);
    const [currentQ, setCurrentQ] = useState(0);
    const [answers, setAnswers] = useState({});
    const [marked, setMarked] = useState(new Set());
    const [timeLeft, setTimeLeft] = useState(0);
    const [questionTimes, setQuestionTimes] = useState({});
    const [lastQTime, setLastQTime] = useState(Date.now());
    const [offlineSyncPending, setOfflineSyncPending] = useState(false);
    const [showNav, setShowNav] = useState(false);
    const [initialReportState, setReportState] = useState({ show: false, reason: 'error', comment: '' });

    // ─── P0-1: Recovery State ───
    const [recoveryState, setRecoveryState] = useState('checking'); // checking | prompt | none
    const [startedAt, setStartedAt] = useState(null);
    const saveInFlightRef = useRef(false);

    // ─── P0-1: Persist full session to IDB ───
    const persistSession = useCallback(async () => {
        if (!testData || saveInFlightRef.current) return;
        saveInFlightRef.current = true;
        try {
            await TestSessionStore.saveSession(testId, {
                testData,
                answers,
                currentQ,
                marked: Array.from(marked),
                questionTimes,
                startedAt,
                timeLeft,
                offlineSyncPending
            });
        } catch (e) {
            console.error('[P0-1] Session persist failed:', e);
        } finally {
            saveInFlightRef.current = false;
        }
    }, [testId, testData, answers, currentQ, marked, questionTimes, startedAt, timeLeft, offlineSyncPending]);

    // ─── P0-1: Mount — Check IDB for recoverable session ───
    useEffect(() => {
        let cancelled = false;

        async function checkRecovery() {
            // 1. Check IDB for existing session for this testId
            const existingSession = await TestSessionStore.loadSession(testId);

            if (existingSession && existingSession.testData && !cancelled) {
                // Recoverable session found — show prompt
                setRecoveryState('prompt');
                // Store recovery data for use when user clicks Resume
                window.__pendingRecovery = existingSession;
                return;
            }

            // 2. No IDB session — try sessionStorage (fresh test from configure page)
            const stored = sessionStorage.getItem('currentTest');
            if (stored && !cancelled) {
                try {
                    const data = JSON.parse(stored);
                    if (data.testId === testId) {
                        const now = Date.now();
                        setTestData(data);
                        setTimeLeft(data.timeLimit);
                        setStartedAt(now);
                        setRecoveryState('none');

                        // Check for partial answer draft in old IDB format
                        const draft = await OfflineStorage.getItem(`draft_${testId}`);
                        if (draft) {
                            setAnswers(draft.answers || {});
                            setOfflineSyncPending(draft.pendingSubmit || false);
                        }

                        // Persist initial session to IDB immediately
                        await TestSessionStore.saveSession(testId, {
                            testData: data,
                            answers: draft?.answers || {},
                            currentQ: 0,
                            marked: [],
                            questionTimes: {},
                            startedAt: now,
                            timeLeft: data.timeLimit,
                            offlineSyncPending: draft?.pendingSubmit || false
                        });
                        return;
                    }
                } catch (e) {
                    console.error('[P0-1] sessionStorage parse failed:', e);
                }
            }

            // 3. Nothing found — redirect to configure
            if (!cancelled) {
                window.location.href = '/test/configure';
            }
        }

        checkRecovery();
        return () => { cancelled = true; };
    }, [testId, router]);

    // ─── P0-1: Resume handler ───
    const handleResume = useCallback(() => {
        const session = window.__pendingRecovery;
        if (!session) return;

        setTestData(session.testData);
        setAnswers(session.answers || {});
        setCurrentQ(session.currentQ || 0);
        setMarked(new Set(session.marked || []));
        setQuestionTimes(session.questionTimes || {});
        setOfflineSyncPending(session.offlineSyncPending || false);
        setStartedAt(session.startedAt);

        // P0-1: Server-truth timer — compute remaining from startedAt
        const elapsed = Math.floor((Date.now() - session.startedAt) / 1000);
        const totalDuration = session.testData.timeLimit;
        const remaining = Math.max(0, totalDuration - elapsed);

        if (remaining <= 0) {
            // Time expired while away — auto-submit
            setTimeLeft(0);
            setRecoveryState('none');
            // Trigger submit after render
            setTimeout(() => handleSubmitDirect(session), 100);
            return;
        }

        setTimeLeft(remaining);
        setRecoveryState('none');
        setShowRecoveryBanner(true);
        delete window.__pendingRecovery;
    }, []);

    // ─── P0-1: Discard handler ───
    const handleDiscard = useCallback(async () => {
        await TestSessionStore.clearSession(testId);
        await OfflineStorage.removeItem(`draft_${testId}`);
        sessionStorage.removeItem('currentTest');
        delete window.__pendingRecovery;
        window.location.href = '/test/configure';
    }, [testId, router]);

    // ─── P0-1: Persist on every state mutation ───
    useEffect(() => {
        if (!testData || recoveryState !== 'none') return;
        persistSession();
    }, [answers, currentQ, marked, questionTimes, testData, recoveryState, persistSession]);

    // ─── P0-1: Heartbeat (every 10 seconds) ───
    useEffect(() => {
        if (!testData || recoveryState !== 'none') return;
        const interval = setInterval(() => persistSession(), 10000);
        return () => clearInterval(interval);
    }, [testData, recoveryState, persistSession]);

    // ─── P0-1: visibilitychange + beforeunload ───
    useEffect(() => {
        if (!testData || recoveryState !== 'none') return;

        const handleVisibility = () => {
            if (document.visibilityState === 'hidden') persistSession();
        };
        const handleUnload = () => {
            // Synchronous signal for localStorage (IDB may not complete)
            try {
                localStorage.setItem(STORAGE_KEYS.ACTIVE_TEST, JSON.stringify({
                    activeTestId: testId,
                    lastUpdatedAt: Date.now(),
                    resumeAvailable: true
                }));
            } catch (e) { /* non-fatal */ }
        };

        document.addEventListener('visibilitychange', handleVisibility);
        window.addEventListener('beforeunload', handleUnload);
        return () => {
            document.removeEventListener('visibilitychange', handleVisibility);
            window.removeEventListener('beforeunload', handleUnload);
        };
    }, [testData, recoveryState, testId, persistSession]);

    // ─── Legacy IDB backup for offline submit ───
    useEffect(() => {
        if (!testData || Object.keys(answers).length === 0) return;
        OfflineStorage.setItem(`draft_${testId}`, { answers, pendingSubmit: offlineSyncPending });
    }, [answers, testData, testId, offlineSyncPending]);

    // ─── Timer ───
    useEffect(() => {
        if (!testData || timeLeft <= 0 || offlineSyncPending || recoveryState !== 'none') return;
        const timer = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) { handleSubmit(); return 0; }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [testData, offlineSyncPending, recoveryState]);

    // ─── MD MANDATE: React Query for Transactional Flows ───
    const reportMutation = useMutation({
        mutationFn: async (reportData) => {
            const res = await fetch('/api/questions/report', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(reportData)
            });
            if (!res.ok) throw new Error('Failed to submit report');
            return res.json().catch(() => ({}));
        },
        onSuccess: () => {
            alert('Report submitted. Thank you for your feedback!');
            setReportState({ show: false, reason: 'error', comment: '' });
        },
        onError: (e) => {
            console.error(e);
            alert('Error submitting report.');
        }
    });

    const submitReport = () => {
        if (!testData) return;
        reportMutation.mutate({
            questionId: testData.questions[currentQ].id,
            reason: initialReportState.reason,
            comment: initialReportState.comment
        });
    };

    const trackTime = useCallback(() => {
        const now = Date.now();
        const elapsed = Math.round((now - lastQTime) / 1000);
        setQuestionTimes(prev => ({
            ...prev,
            [currentQ]: (prev[currentQ] || 0) + elapsed
        }));
        setLastQTime(now);
    }, [currentQ, lastQTime]);

    const handleAnswer = (option) => {
        setAnswers(prev => ({
            ...prev,
            [currentQ]: prev[currentQ] === option ? null : option
        }));
    };

    const handleMark = () => {
        setMarked(prev => {
            const next = new Set(prev);
            if (next.has(currentQ)) next.delete(currentQ);
            else next.add(currentQ);
            return next;
        });
    };

    const goToQuestion = (idx) => {
        trackTime();
        setCurrentQ(idx);
        setShowNav(false);
    };

    // ─── MD MANDATE: React Query for Test Submission & Retries ───
    const testSubmitMutation = useMutation({
        mutationFn: async (payload) => {
            const res = await fetch('/api/tests/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();

            if (res.status === 400 && data.error === 'Test already submitted') {
                return { alreadySubmitted: true };
            }
            if (!res.ok) throw new Error(data.error || 'Network Drop');
            return data;
        },
        retry: 2, // Auto-retry sensitive submissions before offline fallback
        onSuccess: async (data, variables) => {
            if (data.alreadySubmitted) {
                await TestSessionStore.clearSession(testId);
                await OfflineStorage.removeItem(`draft_${testId}`);
                sessionStorage.removeItem('currentTest');
                window.location.href = `/test/${testId}/results`;
                return;
            }

            sessionStorage.setItem('testResults', JSON.stringify(data));
            sessionStorage.removeItem('currentTest');
            await TestSessionStore.clearSession(testId);
            await OfflineStorage.removeItem(`draft_${testId}`);
            window.location.href = `/test/${testId}/results`;
        },
        onError: async (err, variables) => {
            console.error('Submission Failed:', err);
            setOfflineSyncPending(true);
            await OfflineStorage.setItem(`draft_${testId}`, { 
                answers: variables.rawAnswers, 
                pendingSubmit: true, 
                payload: variables 
            });
        }
    });

    // Direct submit with explicit session data (for auto-submit on resume with expired timer)
    const handleSubmitDirect = (session) => {
        if (testSubmitMutation.isPending) return;

        const td = session?.testData || testData;
        const ans = session?.answers || answers;
        const qt = session?.questionTimes || questionTimes;

        const answerPayload = td.questions.map((q, idx) => ({
            questionId: q.id,
            selectedOption: ans[idx] || null,
            timeSpent: qt[idx] || 0
        }));

        const sa = session?.startedAt || startedAt || Date.now();
        const payload = {
            testId,
            answers: answerPayload,
            timeTaken: Math.round((Date.now() - sa) / 1000),
            idempotencyKey: crypto.randomUUID(),
            rawAnswers: ans // pass raw for offline IDB draft
        };

        testSubmitMutation.mutate(payload);
    };

    const handleSubmit = () => {
        if (testSubmitMutation.isPending) return;
        trackTime();
        handleSubmitDirect(null);
    };

    // ─── P0-1: Recovery Prompt UI ───
    if (recoveryState === 'prompt') {
        return (
            <div className="page" style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
                <Card className="animate-fade-in" style={{ maxWidth: 480, width: '100%', textAlign: 'center', padding: '40px 32px' }}>
                    <div style={{ marginBottom: 16 }}><Icon name="FileText" /></div>
                    <h2 style={{ fontWeight: 800, marginBottom: 12, }}>
                        Resume your test?
                    </h2>
                    <p style={{ marginBottom: 32, lineHeight: 1.6 }}>
                        You have an unfinished test. Your answers and progress have been saved.
                    </p>
                    <div style={{ display: 'flex', gap: 12, justifyContent: 'center' }}>
                        <Button variant="primary" size="lg" onClick={handleResume} style={{ minWidth: 160 }}>
                            Resume Test →
                        </Button>
                        <Button variant="ghost" size="lg" onClick={handleDiscard} style={{ minWidth: 120 }}>
                            Discard
                        </Button>
                    </div>
                </Card>
            </div>
        );
    }

    // ─── Checking / Loading ───
    if (recoveryState === 'checking' || !testData) {
        return (
            <div className="loading-overlay" style={{ minHeight: '100vh' }}>
                <div className="spinner" style={{ width: 40, height: 40 }}></div>
            </div>
        );
    }

    const question = testData.questions[currentQ];
    const formatTime = (s) => {
        const h = Math.floor(s / 3600);
        const m = Math.floor((s % 3600) / 60);
        const sec = s % 60;
        return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}` : `${m}:${String(sec).padStart(2, '0')}`;
    };

    const answeredCount = Object.values(answers).filter(a => a).length;

    return (
        <div style={{ minHeight: '100vh' }}>
            <RecoveryBanner show={showRecoveryBanner} />

            {/* Network Fallback Recovery Banner */}
            {offlineSyncPending && (
                <div style={{ padding: '12px 24px', textAlign: 'center', display: 'flex', alignItems: 'center', justifyContent: 'space-between', position: 'relative', boxShadow: 'var(--shadow-xl)' }}>
                    <p style={{ fontWeight: 600, margin: 0 }}><Icon name="AlertCircle" /> Connection dropped. Your test is paused and safely saved offline.</p>
                    <Button onClick={handleSubmit} disabled={testSubmitMutation.isPending} variant="secondary" size="sm">
                        {testSubmitMutation.isPending ? 'Syncing...' : 'Retry Submission Sync'}
                    </Button>
                </div>
            )}

            {/* Test Header */}
            <div className="test-header" style={{ margin: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                    <span className="question-number">Q {currentQ + 1}/{testData.totalQuestions}</span>
                    <span >{answeredCount} answered</span>
                    <div className="hidden md:block">
                        <AutosaveIndicator lastSavedAt={testData ? Date.now() : null} />
                    </div>
                </div>
                <div className={`timer ${timeLeft > 300 ? 'safe' : ''}`}>
                    <Icon name="Clock" /> {formatTime(timeLeft)}
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                    <Button variant="ghost" size="sm" onClick={() => setShowNav(!showNav)}>
                        <Icon name="FileText" /> Navigator
                    </Button>
                    <Button variant="danger" size="sm" onClick={handleSubmit} disabled={testSubmitMutation.isPending} className="critical-flow">
                        {testSubmitMutation.isPending ? 'Submitting...' : 'Submit Test'}
                    </Button>
                </div>
            </div>

            <div style={{ display: 'flex', maxWidth: 1200, margin: '0 auto', padding: 24 }}>
                {/* Main Question Area */}
                <div style={{ flex: 1, paddingRight: showNav ? 24 : 0 }}>
                    <Card className="animate-fade-in" key={currentQ}>
                        {/* Question */}
                        <div className="question-text">
                            {question.is_ai_generated === 1 && (
                                <Badge variant="primary" style={{ marginRight: 8, verticalAlign: 'middle' }}>
                                    <Icon name="Zap" /> AI Generated
                                </Badge>
                            )}
                            {(question.year_asked || question.exam_name) && (
                                <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8, marginRight: 8, verticalAlign: 'middle' }}>
                                    <TrustBadge type="verified-pyq" />
                                    <Badge variant="accent">
                                        {question.exam_name ? `${question.exam_name} ${question.year_asked}` : `NEET ${question.year_asked}`}
                                    </Badge>
                                </span>
                            )}
                            <MathRenderer>{question.text}</MathRenderer>
                        </div>

                        {/* Options */}
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                            {[
                                { key: 'A', text: question.option_a },
                                { key: 'B', text: question.option_b },
                                { key: 'C', text: question.option_c },
                                { key: 'D', text: question.option_d },
                            ].map(opt => (
                                <div key={opt.key}
                                    className={`option-card ${answers[currentQ] === opt.key ? 'selected' : ''}`}
                                    onClick={() => handleAnswer(opt.key)}>
                                    <span className="option-label">{opt.key}</span>
                                    <span style={{ flex: 1 }}><MathRenderer>{opt.text}</MathRenderer></span>
                                </div>
                            ))}
                        </div>
                    </Card>

                    {/* Navigation Buttons */}
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 16 }}>
                        <div style={{ display: 'flex', gap: 8 }}>
                            <Button variant="secondary" onClick={() => goToQuestion(Math.max(0, currentQ - 1))} disabled={currentQ === 0}>
                                ← Previous
                            </Button>
                            <Button variant={marked.has(currentQ) ? 'primary' : 'ghost'} onClick={handleMark}>
                                {marked.has(currentQ) ? '🔖 Marked' : '🔖 Mark'}
                            </Button>
                            <Button variant="ghost" title="Report Issue" onClick={() => setReportState({ ...initialReportState, show: true })}>
                                🚩
                            </Button>
                        </div>
                        <div style={{ display: 'flex', gap: 8 }}>
                            {answers[currentQ] && (
                                <Button variant="ghost" size="sm" onClick={() => handleAnswer(answers[currentQ])}>Clear</Button>
                            )}
                            {currentQ < testData.totalQuestions - 1 ? (
                                <Button variant="primary" onClick={() => goToQuestion(currentQ + 1)}>
                                    Next →
                                </Button>
                            ) : (
                                <Button variant="success" onClick={handleSubmit} disabled={testSubmitMutation.isPending} className="critical-flow">
                                    Submit Test ✓
                                </Button>
                            )}
                        </div>
                    </div>
                </div>

                {/* Question Navigator Panel */}
                {showNav && (
                    <Card className="animate-slide-in" style={{ width: 280, flexShrink: 0, alignSelf: 'flex-start', position: 'sticky', top: 140 }}>
                        <h4 style={{ marginBottom: 16, fontWeight: 800 }}>Question Navigator</h4>
                        <div className="question-nav">
                            {testData.questions.map((_, idx) => (
                                <div key={idx} role="button"
                                    className={`question-nav-btn ${idx === currentQ ? 'current' : ''} ${answers[idx] ? 'answered' : ''} ${marked.has(idx) ? 'marked' : ''}`}
                                    onClick={() => goToQuestion(idx)}>
                                    {idx + 1}
                                </div>
                            ))}
                        </div>
                        <div style={{ marginTop: 16, display: 'flex', flexDirection: 'column', gap: 8, }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                <span className="question-nav-btn current" style={{ width: 16, height: 16, minWidth: 16 }}></span> Current
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                <span className="question-nav-btn answered" style={{ width: 16, height: 16, minWidth: 16 }}></span> Answered
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                <span className="question-nav-btn marked" style={{ width: 16, height: 16, minWidth: 16 }}></span> Marked
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                <span className="question-nav-btn" style={{ width: 16, height: 16, minWidth: 16 }}></span> Not visited
                            </div>
                        </div>
                    </Card>
                )}
            </div>

            {/* Report Modal */}
            {initialReportState.show && (
                <div className="modal-overlay">
                    <Card className="modal-content animate-scale-in">
                        <h3 style={{ fontWeight: 800, marginBottom: 8 }}>Report Issue with Q{currentQ + 1}</h3>
                        <p style={{ marginBottom: 16, }}>Help us improve question quality.</p>

                        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 16 }}>
                            <Select value={initialReportState.reason} onChange={(e) => setReportState({ ...initialReportState, reason: e.target.value })}>
                                <option value="error">Factual Error</option>
                                <option value="ambiguous">Ambiguous / Confusing</option>
                                <option value="syllabus">Out of Syllabus</option>
                                <option value="other">Other</option>
                            </Select>
                            <Textarea
                                placeholder="Describe the issue..."
                                rows={3}
                                value={initialReportState.comment}
                                onChange={(e) => setReportState({ ...initialReportState, comment: e.target.value })}
                            />
                        </div>

                        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                            <Button variant="ghost" onClick={() => setReportState({ show: false, reason: 'error', comment: '' })}>Cancel</Button>
                            <Button variant="danger" onClick={submitReport} loading={reportMutation.isPending}>Submit Report</Button>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
}

import { Icon } from '@/components/ui/Icon';
'use client';
import { useState, useEffect, use } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Card, Button, Badge, Skeleton } from '@/components/ui';
import { TrustBadge } from '@/components/trust/TrustBadge';
import { openWhatsAppShare } from '@/lib/utils/whatsapp';

export default function ResultsPage({ params }) {
    const { id: testId } = use(params);
    const router = useRouter();
    const [results, setResults] = useState(null);
    const [showExplanation, setShowExplanation] = useState({});

    useEffect(() => {
        const stored = sessionStorage.getItem('testResults');
        if (stored) {
            setResults(JSON.parse(stored));
            if (typeof window.showInterstitialAd === 'function') {
                setTimeout(() => window.showInterstitialAd(), 1500);
            }
            return;
        }
        window.location.href = '/dashboard';
    }, [router]);

    if (!results) return (
        <div className="page results-wrapper" style={{ minHeight: 'calc(100vh - 64px)' }}>
            <Card style={{ marginBottom: 24, textAlign: 'center', padding: 40 }}>
                <Skeleton style={{ width: 120, height: 60, margin: '0 auto 16px' }} />
                <Skeleton style={{ width: 80, height: 24, margin: '0 auto 32px' }} />
                <Skeleton style={{ height: 12, width: '100%', marginBottom: 32 }} />
                <div className="grid grid-4"><Skeleton style={{ height: 80 }} /><Skeleton style={{ height: 80 }} /><Skeleton style={{ height: 80 }} /><Skeleton style={{ height: 80 }} /></div>
            </Card>
        </div>
    );

    const { score, xpEarned, level, answers, referralRewardUnlocked } = results;

    const toggleExplanation = (idx) => {
        setShowExplanation(prev => ({ ...prev, [idx]: !prev[idx] }));
    };

    // Severity → background/border helper (dynamic, kept in JS)
    function trustCardStyle(severity) {
        const map = {
            success: { bg: 'rgba(34,197,94,0.05)', border: 'rgba(34,197,94,0.2)' },
            warning: { bg: 'rgba(245,158,11,0.05)', border: 'rgba(245,158,11,0.2)' },
            danger:  { bg: 'rgba(239,68,68,0.05)',  border: 'rgba(239,68,68,0.2)' },
        };
        const s = map[severity] || map.danger;
        return { background: s.bg, border: `1px solid ${s.border}` };
    }
    function trustMsgColor(severity) {
        const map = { success: 'var(--success)', warning: 'var(--warning)', danger: 'var(--danger)' };
        return map[severity] || 'var(--danger)';
    }

    return (
        <div className="page">
            <div className="results-wrapper">

                {/* Score Display */}
                <Card className="animate-fade-in-up" style={{ marginBottom: 24, padding: '40px 24px' }}>
                    <div className="results-score-section">
                        <div className="results-score-value">{score.scaledScore}</div>
                        <div className="results-score-label">out of 720</div>

                        <div className="results-bar">
                            <div className="results-bar-correct" style={{ flex: score.correct }} />
                            <div className="results-bar-incorrect" style={{ flex: score.incorrect }} />
                            <div className="results-bar-unanswered" style={{ flex: score.unanswered }} />
                        </div>

                        <div className="grid grid-4" style={{ gap: 16 }}>
                            <Card className="results-mini-card">
                                <div className="results-mini-value" >{score.correct}</div>
                                <div className="results-mini-label">Correct (+{score.correct * 4})</div>
                            </Card>
                            <Card className="results-mini-card">
                                <div className="results-mini-value" >{score.incorrect}</div>
                                <div className="results-mini-label">Incorrect (-{score.incorrect})</div>
                            </Card>
                            <Card className="results-mini-card">
                                <div className="results-mini-value" >{score.unanswered}</div>
                                <div className="results-mini-label">Unanswered</div>
                            </Card>
                            <Card className="results-mini-card">
                                <div className="results-mini-value" >{score.accuracy}%</div>
                                <div className="results-mini-label">Accuracy</div>
                            </Card>
                        </div>
                    </div>
                </Card>

                {/* Referral Reward */}
                {referralRewardUnlocked && (
                    <Card className="animate-fade-in-up results-referral-card">
                        <h3 className="results-referral-title"><Icon name="Star" size={16} /> Referral Validated!</h3>
                        <p className="results-referral-body">
                            You and your friend both earned <strong >+20 Trust Score</strong> and unlocked <strong >24h of Premium AI!</strong>
                        </p>
                        <Badge variant="accent" style={{ padding: '8px 16px', }}>
                            <Icon name="Flame" /> Invite 3 more friends → Unlock 7 days premium!
                        </Badge>
                    </Card>
                )}

                {/* XP & Level */}
                <div className="grid grid-2 results-xp-cards">
                    <Card className="results-xp-card">
                        <div className="results-xp-icon"><Icon name="Star" /></div>
                        <div className="results-xp-value">+{xpEarned} XP</div>
                        <div className="results-xp-label">Experience Earned</div>
                    </Card>
                    <Card className="results-xp-card">
                        <div className="results-xp-icon"><Icon name="Star" size={16} />️</div>
                        <div className="results-xp-value">Level {level.level}</div>
                        <div className="results-xp-label">{level.name}</div>
                    </Card>
                </div>

                {/* Momentum nudge */}
                <Card style={{ padding: 16, marginBottom: 24, textAlign: 'center', }}>
                    <p style={{ margin: 0, fontWeight: 600, }}>
                        You are extremely close to Level {level.level + 1}. <span >Take 1 more test to rank up!</span>
                    </p>
                </Card>

                {/* Next-Action */}
                <Card style={{ padding: 32, marginBottom: 24, textAlign: 'center', border: '1px solid var(--border-color)' }}>
                    <h3 style={{ margin: '0 0 12px', fontWeight: 800, }}><Icon name="Brain" /> Keep the Momentum Going</h3>
                    <p style={{ marginBottom: 24, }}>Your physics logic starts decaying when you only focus on Biology. Maintain your All-India rank streak.</p>
                    <Link href="/test/configure">
                        <Button variant="accent" size="lg">Switch Physics Weaknesses Now →</Button>
                    </Link>
                </Card>

                {/* Trust Status Hint — dynamic severity, kept as inline style */}
                {results.trustHint && (
                    <Card className="animate-fade-in results-trust-card" style={trustCardStyle(results.trustHint.severity)}>
                        <p className="results-trust-msg" style={{ color: trustMsgColor(results.trustHint.severity) }}>
                            {results.trustHint.severity === 'success' ? '🌟' : results.trustHint.severity === 'warning' ? '<Icon name="AlertCircle" />' : '<Icon name="Lock" />'} {results.trustHint.message}
                        </p>
                    </Card>
                )}

                {/* Actions */}
                <div className="results-actions">
                    <Link href="/test/configure"><Button variant="primary"><Icon name="FileText" /> Take Another Test</Button></Link>
                    <Link href="/analytics"><Button variant="secondary"><Icon name="BarChart2" /> View Analytics</Button></Link>
                    <Link href="/dashboard"><Button variant="secondary"><Icon name="Star" size={16} /> Dashboard</Button></Link>
                    <Button
                        variant="success"
                        className="results-share-btn"
                        onClick={() => {
                            const text = `I just scored ${score.scaledScore}/720 on my AI NEET Mock Test! <Icon name="Zap" />\n\nCheck out my scorecard and rank prediction here:\nhttps://aineetcoach.com/test/${testId}/share`;
                            openWhatsAppShare(text);
                        }}
                    >
                        📱 Share to WhatsApp
                    </Button>
                </div>

                {/* Answer Review */}
                <div className="results-review-section">
                    <h2 className="results-review-title"><Icon name="FileText" /> Answer Review</h2>
                    <div className="results-review-list">
                        {answers.map((a, idx) => (
                            <div key={idx} className="animate-fade-in" style={{ animationDelay: `${Math.min(idx * 0.03, 0.5)}s` }}>
                                <Card style={{
                                    padding: 24, border: `1px solid ${a.is_correct ? 'var(--bg-glass)' : a.selected_option ? 'var(--bg-glass)' : 'var(--border-color)'}`
                                }}>
                                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                            <Badge variant="secondary" style={{ fontWeight: 700 }}>Question {idx + 1}</Badge>
                                            {(a.year_asked || a.exam_name) && <TrustBadge type="verified-pyq" />}
                                            {a.is_teacher_reviewed && <TrustBadge type="teacher-reviewed" />}
                                        </div>
                                        <span className={`results-option-tag results-option-tag--${a.is_correct ? 'correct' : a.selected_option ? 'wrong' : ''}`}
                                            style={!a.is_correct && !a.selected_option ? { fontWeight: 800 } : { fontWeight: 800 }}>
                                            {a.is_correct ? '✓ Correct (+4)' : a.selected_option ? '✗ Incorrect (-1)' : '— Skipped (0)'}
                                        </span>
                                    </div>

                                    <p style={{ marginBottom: 20, lineHeight: 1.6 }}>{a.text}</p>

                                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                                        {[
                                            { key: 'A', text: a.option_a },
                                            { key: 'B', text: a.option_b },
                                            { key: 'C', text: a.option_c },
                                            { key: 'D', text: a.option_d },
                                        ].map(opt => {
                                            const isCorrect = opt.key === a.correct_option;
                                            const isWrong = opt.key === a.selected_option && !a.is_correct;
                                            const variant = isCorrect ? 'correct' : isWrong ? 'wrong' : 'neutral';

                                            return (
                                                <div key={opt.key} style={{
                                                    display: 'flex', alignItems: 'center', gap: 16, padding: '12px 16px',
                                                    background: isCorrect ? 'var(--bg-glass)' : isWrong ? 'var(--bg-glass)' : 'var(--bg-card)',
                                                    border: `1px solid ${isCorrect ? 'var(--bg-glass)' : isWrong ? 'var(--bg-glass)' : 'var(--border-color)'}`,
                                                    }}>
                                                    <div className={`results-option-key results-option-key--${variant}`}>{opt.key}</div>
                                                    <span className={`results-option-label--${variant}`} style={{ flex: 1, }}>{opt.text}</span>
                                                    {isCorrect && <span className="results-option-tag results-option-tag--correct"><Icon name="Star" size={16} /> Correct</span>}
                                                    {isWrong && <span className="results-option-tag results-option-tag--wrong">Your answer</span>}
                                                </div>
                                            );
                                        })}
                                    </div>

                                    <div style={{ marginTop: 20 }}>
                                        <Button variant="outline" size="sm" onClick={() => toggleExplanation(idx)}>
                                            {showExplanation[idx] ? '🔽 Hide Explanation' : '💡 Show Explanation'}
                                        </Button>
                                    </div>

                                    {showExplanation[idx] && (
                                        <div className="results-explanation">
                                            <div className="results-explanation-header">
                                                <h4 className="results-explanation-title"><Icon name="Star" size={16} /> Explanation</h4>
                                                {(a.is_ai_generated === 1 || a.ai_confidence) && (
                                                    <TrustBadge type="ai-confidence" meta={{ score: a.ai_confidence || 0.95 }} />
                                                )}
                                            </div>
                                            {a.explanation ? (
                                                <p style={{ lineHeight: 1.6 }}>{a.explanation}</p>
                                            ) : (
                                                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                                                    <p >No specific explanation available.</p>
                                                    <Link href={`/doubts?q=${encodeURIComponent('Please explain this NEET question: ' + a.text + ' The correct option is ' + a.correct_option)}`}>
                                                        <Button variant="secondary" size="sm"><Icon name="Cpu" /> Ask AI Coach to Explain</Button>
                                                    </Link>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </Card>
                            </div>
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
}

import { Icon } from '@/components/ui/Icon';
'use client';
import { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import AppInstallPrompt from '@/components/AppInstallPrompt';
import { useAuth } from '@/context/AuthContext';
import { Card, Button, Input } from '@/components/ui';

function TestConfigContent() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const [syllabus, setSyllabus] = useState([]);
    const [selectedSubjects, setSelectedSubjects] = useState([]);
    const [selectedChapters, setSelectedChapters] = useState([]);
    const [selectedTopics, setSelectedTopics] = useState([]);
    const [difficulty, setDifficulty] = useState('all');
    const [questionCount, setQuestionCount] = useState(20);
    const [testType, setTestType] = useState(searchParams.get('type') || 'custom');

    // Yearly PYQ States
    const [availableYears, setAvailableYears] = useState([]);
    const [selectedYear, setSelectedYear] = useState('');

    const [loading, setLoading] = useState(true);
    const [generating, setGenerating] = useState(false);
    const [error, setError] = useState('');
    const { user } = useAuth();
    const [showLockModal, setShowLockModal] = useState(false);
    const [lockMessage, setLockMessage] = useState('');
    const [showAppPromo, setShowAppPromo] = useState(false);

    useEffect(() => {
        fetch('/api/syllabus').then(r => r.json()).then(data => {
            setSyllabus(data.subjects || []);
            setLoading(false);
        });
        // Fetch available PYQ years
        fetch('/api/pyq/years').then(r => r.json()).then(data => {
            if (data.years && data.years.length > 0) {
                setAvailableYears(data.years);
                setSelectedYear(data.years[0]);
            }
        });
    }, [router]);

    const toggleSubject = (id) => {
        setSelectedSubjects(prev =>
            prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
        );
    };

    const toggleChapter = (id) => {
        setSelectedChapters(prev =>
            prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]
        );
    };

    const toggleTopic = (id) => {
        setSelectedTopics(prev =>
            prev.includes(id) ? prev.filter(t => t !== id) : [...prev, id]
        );
    };

    const handleGenerate = async () => {
        if (!user) {
            window.location.href = '/login?redirect=/test/configure';
            return;
        }
        // App Install Gate for Mobile Web ONLY
        // Do NOT block users already inside the native app (ReactNativeWebView or custom UA header)
        if (typeof window !== 'undefined') {
            const isMobileBrowser = Boolean(navigator.userAgent.match(/Android|BlackBerry|iPhone|iPad|iPod|Opera Mini|IEMobile|WPDesktop/i));
            const isInsideNativeApp = Boolean(
                window.ReactNativeWebView ||                          // React Native WebView bridge
                window.nativeApp ||                                    // Custom bridge if set
                navigator.userAgent.includes('NEETCoachApp') ||       // Custom UA we can set in the app
                document.cookie.includes('native_app=true')           // Cookie set by native app on boot
            );
            if (isMobileBrowser && !isInsideNativeApp) {
                setShowAppPromo(true);
                return;
            }
        }

        setGenerating(true);
        setError('');
        try {
            let endpoint = '/api/tests/generate';
            if (testType === 'adaptive') endpoint = '/api/tests/adaptive';
            if (testType === 'pyq') endpoint = '/api/tests/pyq';

            // For custom tests, if they selected specific chapters, we only send those chapters
            // so we don't accidentally restrict them by the 'subjects' filter if they mixed and matched.
            const apiSubjects = (testType === 'custom' && selectedChapters.length > 0)
                ? undefined
                : (selectedSubjects.length > 0 ? selectedSubjects : syllabus.map(s => s.id));

            const payload = {
                subjects: apiSubjects,
                subjectId: testType === 'adaptive' ? selectedSubjects[0] : undefined,
                chapters: selectedChapters.length > 0 ? selectedChapters : undefined,
                topics: selectedTopics.length > 0 ? selectedTopics : undefined,
                difficulty: (testType !== 'pyq' && testType !== 'yearly_pyq' && difficulty !== 'all') ? difficulty : undefined,
                questionCount: (testType === 'mock' || testType === 'yearly_pyq') ? 180 : questionCount,
                count: questionCount,
                type: testType,
                year: testType === 'yearly_pyq' ? selectedYear : undefined
            };

            const res = await fetch(endpoint, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();

            if (!res.ok) {
                if (data.locked) {
                    setLockMessage(data.error);
                    setShowLockModal(true);
                    return;
                }
                throw new Error(data.error);
            }

            sessionStorage.setItem('currentTest', JSON.stringify(data));
            window.location.href = `/test/${data.testId}`;
        } catch (err) {
            setError(err.message);
        } finally { setGenerating(false); }
    };

    if (loading) return (
        <div className="loading-overlay" style={{ minHeight: '100vh' }}>
            <div className="spinner" style={{ width: 40, height: 40 }}></div>
        </div>
    );

    // We determine which subjects to show chapters for. If no subject selected, show all.
    const activeSubjectsForChapters = selectedSubjects.length > 0
        ? syllabus.filter(s => selectedSubjects.includes(s.id))
        : syllabus;

    return (
        <div>

            <AppInstallPrompt mode="hard" showModal={showAppPromo} onClose={() => setShowAppPromo(false)} />

            <div className="page" style={{ maxWidth: 900 }}>
                <div className="page-header">
                    <h1 className="page-title"><Icon name="Target" /> Generate AI Test</h1>
                    <p className="page-subtitle">Configure your test and start practicing</p>
                </div>

                {error && (
                    <Card style={{ padding: '12px 16px', border: '1px solid rgba(239,68,68,0.3)', marginBottom: 20 }}>
                        {error}
                    </Card>
                )}

                {/* Test Type */}
                <Card style={{ marginBottom: 24 }}>
                    <h3 style={{ marginBottom: 16, fontWeight: 800 }}>Test Type</h3>
                    <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                        {[
                            { value: 'custom', label: 'Custom Test', icon: '<Icon name="Target" />', desc: 'Choose your own settings' },
                            { value: 'adaptive', label: 'Adaptive Practice', icon: '<Icon name="Brain" />', desc: 'AI Adjusts Difficulty' },
                            { value: 'ai_generated', label: 'AI Generated', icon: '<Icon name="Zap" />', desc: 'Unique AI questions' },
                            { value: 'pyq', label: 'Past Papers (Topic)', icon: '<Icon name="FileText" />', desc: 'Filter by chapter' },
                            { value: 'yearly_pyq', label: 'Year-wise PYQ', icon: '<Icon name="CalendarDays" />', desc: 'Full papers by year' },
                            { value: 'topic', label: 'Topic-wise', icon: '📌', desc: 'Focus on specific topics' },
                            { value: 'chapter', label: 'Chapter-wise', icon: '📖', desc: 'Complete chapter test' },
                            { value: 'mock', label: 'Full Mock', icon: '<Icon name="Clock" />', desc: '180 Qs • 720 marks' },
                        ].map(t => (
                            <div key={t.value} className={`option-card ${testType === t.value ? 'selected' : ''}`}
                                onClick={() => {
                                    if (testType !== t.value) {
                                        setTestType(t.value);
                                        setSelectedSubjects([]);
                                        setSelectedChapters([]);
                                        setSelectedTopics([]);
                                        setDifficulty('all');
                                    }
                                }} style={{ flex: '1 1 180px' }}>
                                <span >{t.icon}</span>
                                <div>
                                    <div style={{ fontWeight: 600 }}>{t.label}</div>
                                    <div >{t.desc}</div>
                                </div>
                            </div>
                        ))}
                    </div>
                </Card>

                {testType === 'yearly_pyq' && (
                    <Card style={{ marginBottom: 24, border: '2px solid var(--primary)' }}>
                        <h3 style={{ marginBottom: 16, fontWeight: 800 }}>Select PYQ Year</h3>
                        {availableYears.length > 0 ? (
                            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                                {availableYears.map(year => (
                                    <div key={year} className={`option-card ${selectedYear === year ? 'selected' : ''}`}
                                        onClick={() => setSelectedYear(year)} style={{ flex: '1 1 120px', textAlign: 'center' }}>
                                        <span style={{ fontWeight: 800, }}>{year}</span>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <Card style={{ padding: 24, textAlign: 'center', border: '1px solid var(--border)' }}>
                                <Icon name="CalendarDays" /> No full yearly papers available yet. They are coming soon!
                            </Card>
                        )}
                        <p style={{ marginTop: 16, }}>
                            This will generate a full 180-question mock test containing all Botany, Zoology, Physics, and Chemistry questions exactly as they appeared in the {selectedYear} paper.
                        </p>
                    </Card>
                )}

                {testType !== 'mock' && testType !== 'yearly_pyq' && (
                    <>
                        {/* Subject Selection */}
                        <Card style={{ marginBottom: 24 }}>
                            <h3 style={{ marginBottom: 16, fontWeight: 800 }}>Select Subjects</h3>
                            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                                {syllabus.map(s => (
                                    <div key={s.id}
                                        className={`option-card ${selectedSubjects.includes(s.id) ? 'selected' : ''}`}
                                        onClick={() => toggleSubject(s.id)}
                                        style={{ flex: '1 1 150px', borderColor: selectedSubjects.includes(s.id) ? s.color : undefined }}>
                                        <span >{s.icon}</span>
                                        <div style={{ fontWeight: 600 }}>{s.name}</div>
                                    </div>
                                ))}
                            </div>
                            {selectedSubjects.length === 0 && (
                                <p style={{ marginTop: 8 }}>
                                    {testType === 'adaptive' ? 'Please select a subject to start adaptive practice' : 'No selection = all subjects included'}
                                </p>
                            )}
                        </Card>

                        {/* Chapter Selection */}
                        {testType !== 'adaptive' && testType !== 'ai_generated' && (
                            <Card style={{ marginBottom: 24 }}>
                                <h3 style={{ marginBottom: 8, fontWeight: 800 }}>Select Specific Chapters <span style={{ fontWeight: 400 }}>(Mix and match items across subjects)</span></h3>
                                <p style={{ marginBottom: 24 }}>If you pick specific chapters, your test will only include questions from those chapters.</p>

                                <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
                                    {activeSubjectsForChapters.map(subject => (
                                        <div key={subject.id}>
                                            <h4 style={{ color: subject.color, marginBottom: 12, borderBottom: `1px solid ${subject.color}33`, paddingBottom: 8 }}>
                                                {subject.icon} {subject.name}
                                            </h4>
                                            <div className="chapter-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))' }}>
                                                {subject.chapters.map(c => {
                                                    const isDisabled = testType === 'pyq' && c.pyq_count === 0;
                                                    return (
                                                        <div key={c.id}
                                                            className={`chapter-item ${selectedChapters.includes(c.id) ? 'selected' : ''} ${isDisabled ? 'disabled' : ''}`}
                                                            onClick={() => { if (!isDisabled) toggleChapter(c.id); }}
                                                            style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', border: '1px solid var(--border)', cursor: isDisabled ? 'not-allowed' : 'pointer', transition: 'all 0.2s', background: selectedChapters.includes(c.id) ? `${subject.color}15` : 'transparent', borderColor: selectedChapters.includes(c.id) ? subject.color : 'var(--border)', opacity: isDisabled ? 0.5 : 1 }}
                                                        >
                                                            <div style={{ width: 20, height: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', background: selectedChapters.includes(c.id) ? subject.color : 'var(--bg-glass)', fontWeight: 700 }}>
                                                                {selectedChapters.includes(c.id) && '✓'}
                                                                {isDisabled && '🚫'}
                                                            </div>
                                                            <div style={{ flex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                                <div style={{ fontWeight: selectedChapters.includes(c.id) ? 600 : 400, color: selectedChapters.includes(c.id) ? 'var(--text-primary)' : 'var(--text-secondary)' }}>
                                                                    {c.name}
                                                                </div>
                                                                {testType === 'pyq' && (
                                                                    <div style={{ color: isDisabled ? 'var(--danger)' : 'var(--text-muted)' }}>
                                                                        {c.pyq_count} PYQs
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </Card>
                        )}

                        {/* Topic Selection for Topic-wise test */}
                        {testType === 'topic' && selectedChapters.length > 0 && (
                            <Card style={{ marginBottom: 24, marginTop: 16 }}>
                                <h3 style={{ marginBottom: 8, fontWeight: 800 }}>Select Specific Topics</h3>
                                <p style={{ marginBottom: 24 }}>Choose the exact topics from your selected chapters.</p>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
                                    {activeSubjectsForChapters.map(subject => {
                                        const activeChapters = subject.chapters.filter(c => selectedChapters.includes(c.id));
                                        if (activeChapters.length === 0) return null;
                                        return (
                                            <div key={`topics-${subject.id}`}>
                                                {activeChapters.map(c => (
                                                    <div key={c.id} style={{ marginBottom: 16 }}>
                                                        <h5 style={{ color: subject.color, marginBottom: 8, }}>{c.name}</h5>
                                                        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                                                            {c.topics && c.topics.map(t => (
                                                                <div key={t.id}
                                                                    onClick={() => toggleTopic(t.id)}
                                                                    className={`pill ${selectedTopics.includes(t.id) ? 'active' : ''}`}
                                                                    style={{
                                                                        padding: '6px 12px', cursor: 'pointer',
                                                                        background: selectedTopics.includes(t.id) ? subject.color : 'var(--bg-glass)',
                                                                        color: selectedTopics.includes(t.id) ? 'var(--text-primary)' : 'var(--text-secondary)',
                                                                        border: `1px solid ${selectedTopics.includes(t.id) ? subject.color : 'var(--border)'}`
                                                                    }}
                                                                >
                                                                    {t.name}
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        );
                                    })}
                                </div>
                            </Card>
                        )}

                        {/* Difficulty & Count */}
                        <div className="grid grid-2" style={{ gap: 16, marginBottom: 16 }}>
                            {(testType === 'custom' || testType === 'ai_generated') && (
                                <Card>
                                    <h3 style={{ marginBottom: 16, fontWeight: 800 }}>Difficulty Level</h3>
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                                        {['all', 'easy', 'medium', 'hard', 'neet'].map(d => (
                                            <div key={d} className={`option-card ${difficulty === d ? 'selected' : ''}`}
                                                onClick={() => setDifficulty(d)} style={{ padding: '12px 16px' }}>
                                                <span className={`difficulty-badge ${d}`}>
                                                    {d === 'all' ? '🌟 All Levels' : d.charAt(0).toUpperCase() + d.slice(1)}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                </Card>
                            )}
                            <Card>
                                <h3 style={{ marginBottom: 16, fontWeight: 800 }}>Number of Questions</h3>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                                    {[10, 20, 50, 90, 180].map(n => (
                                        <div key={n} className={`option-card ${questionCount === n ? 'selected' : ''}`}
                                            onClick={() => setQuestionCount(n)} style={{ padding: '12px 16px' }}>
                                            <span style={{ fontWeight: 600 }}>{n} Questions</span>
                                            <span >({n * 4} marks • {Math.round(n * 1.5)} min)</span>
                                        </div>
                                    ))}
                                </div>
                            </Card>
                        </div>
                    </>
                )}

                {/* Generate Button */}
                <Button
                    variant="primary"
                    size="lg"
                    onClick={handleGenerate}
                    disabled={generating || (testType === 'yearly_pyq' && !selectedYear)}
                    style={{ width: '100%', padding: '18px 32px' }}
                >
                    {generating ? (
                        <><div className="spinner" style={{ width: 20, height: 20, borderWidth: 2 }}></div> Generating Test...</>
                    ) : testType === 'yearly_pyq' && selectedYear ? (
                        <><Icon name="Zap" /> Generate {selectedYear} PYQ Paper</>
                    ) : (
                        <><Icon name="Zap" /> Generate & Start Test</>
                    )}
                </Button>
            </div>

            {/* Referral Lock Modal */}
            {showLockModal && (
                <div className="modal-overlay" style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
                    <Card className="modal-content" style={{ border: '1px solid var(--border)', padding: 40, maxWidth: 500, width: '100%', textAlign: 'center', position: 'relative' }}>
                        <Button variant="ghost" onClick={() => setShowLockModal(false)} style={{ position: 'absolute', top: 20, right: 20 }}>×</Button>

                        <div style={{ marginBottom: 20 }}><Icon name="Lock" /></div>
                        <h2 style={{ fontWeight: 800, marginBottom: 16, }}>Premium Feature Locked</h2>
                        <p style={{ marginBottom: 32, lineHeight: 1.6 }}>
                            {lockMessage}
                        </p>

                        <Card style={{ border: '1px dashed var(--primary)', padding: 20, marginBottom: 32 }}>
                            <div style={{ marginBottom: 10, textTransform: 'uppercase', letterSpacing: 1 }}>Your Unique Invite Link</div>
                            <div style={{ display: 'flex', gap: 10, alignItems: 'center', padding: 10, }}>
                                <Input
                                    type="text"
                                    readOnly
                                    value={`https://aineetcoach.com/register?ref=${user?.referral_code || ''}`}
                                    style={{ flex: 1, margin: 0 }}
                                />
                                <Button
                                    onClick={() => navigator.clipboard.writeText(`https://aineetcoach.com/register?ref=${user?.referral_code || ''}`)}
                                    variant="secondary"
                                    size="sm"
                                >
                                    Copy
                                </Button>
                            </div>
                        </Card>

                        <Button
                            onClick={() => {
                                const text = `Join AI NEET Coach with me and get free AI Mock Tests! <Icon name="Zap" />\n\nSign up here: https://aineetcoach.com/register?ref=${user?.referral_code || ''}`;
                                window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
                            }}
                            variant="success"
                            size="lg"
                            style={{ width: '100%', padding: 16 }}
                        >
                            📱 Share via WhatsApp
                        </Button>
                    </Card>
                </div>
            )}
        </div >
    );
}

